export const VOD_AVAILABLE = VOD_TITLES;
export function getVodTitle(id: string): VodTitle | undefined {
  return VOD_TITLES.find((t) => t.id === id);
}
export function vodByCategory(category: string, limit = 30): VodTitle[] {
  return VOD_TITLES.filter((t) => t.category === category).slice(0, limit);
}
export const VOD_GENRES = Array.from(new Set(VOD_TITLES.flatMap((t) => t.genres))).sort();
